function JV_MASCOT(m){
  var base='<ellipse cx="32" cy="45" rx="16" ry="12" fill="#9CA7AF"/>' /* body */
  +'<ellipse cx="16" cy="16" rx="5" ry="6.5" fill="#8E99A1"/><ellipse cx="16" cy="16.5" rx="2.6" ry="3.6" fill="#6E7A83"/>' /* left ear */
  +'<ellipse cx="48" cy="16" rx="5" ry="6.5" fill="#8E99A1"/><ellipse cx="48" cy="16.5" rx="2.6" ry="3.6" fill="#6E7A83"/>' /* right ear */
  +'<circle cx="32" cy="30" r="16" fill="#A7B1B8"/>' /* head */
  +'<ellipse cx="32" cy="41.5" rx="9.5" ry="7" fill="#C2CAD0"/>' /* muzzle */
  +'<path d="M29.8 39.5 Q32 28.5 34.2 39.5 Q32 38 29.8 39.5 Z" fill="#7E8992"/>' /* nose horn */
  +'<circle cx="27.5" cy="43" r="1.4" fill="#5D6870"/><circle cx="36.5" cy="43" r="1.4" fill="#5D6870"/>'; /* nostrils */
  var f;
  if(m==='cheer')f='<path d="M22 28.5 Q25 25 28 28.5" fill="none" stroke="#3E4750" stroke-width="2.2" stroke-linecap="round"/><path d="M36 28.5 Q39 25 42 28.5" fill="none" stroke="#3E4750" stroke-width="2.2" stroke-linecap="round"/><path d="M27 46.5 Q32 50.5 37 46.5" fill="none" stroke="#3E4750" stroke-width="2.2" stroke-linecap="round"/>';
  else if(m==='oops')f='<path d="M21.5 26.5 Q25 25.3 28.5 26.5" fill="none" stroke="#3E4750" stroke-width="1.6" stroke-linecap="round"/><path d="M35.5 26.5 Q39 25.3 42.5 26.5" fill="none" stroke="#3E4750" stroke-width="1.6" stroke-linecap="round"/><circle cx="25" cy="29.5" r="2" fill="#3E4750"/><circle cx="39" cy="29.5" r="2" fill="#3E4750"/><ellipse cx="32" cy="47" rx="2.2" ry="2.8" fill="#3E4750"/>';
  else f='<circle cx="25" cy="29" r="2.5" fill="#3E4750"/><circle cx="39" cy="29" r="2.5" fill="#3E4750"/><circle cx="25.8" cy="28.2" r="0.7" fill="#fff"/><circle cx="39.8" cy="28.2" r="0.7" fill="#fff"/><path d="M28 46.5 Q32 49.3 36 46.5" fill="none" stroke="#3E4750" stroke-width="2" stroke-linecap="round"/>';
  return '<svg viewBox="0 0 64 64" width="100%" height="100%" xmlns="http://www.w3.org/2000/svg">'+base+f+'</svg>';}

